import random
import nltk
from nltk.corpus import wordnet

nltk.download('wordnet', quiet=True)

class TextAugmenter:
    def __init__(self, sr_prob=0.3, ri_prob=0.3, rs_prob=0.3, rd_prob=0.2):
        self.sr_prob = sr_prob
        self.ri_prob = ri_prob
        self.rs_prob = rs_prob
        self.rd_prob = rd_prob

    def _get_synonyms(self, word):
        synonyms = []
        for synset in wordnet.synsets(word):
            for lemma in synset.lemmas():
                syn = lemma.name().replace('_', ' ')
                if syn.lower() != word.lower():
                    synonyms.append(syn)
        return list(set(synonyms))

    def synonym_replacement(self, text, n=2):
        words = text.split()
        candidates = [(i, self._get_synonyms(w)) for i, w in enumerate(words)]
        candidates = [(i, s) for i, s in candidates if s]
        random.shuffle(candidates)
        for i, syns in candidates[:n]:
            words[i] = random.choice(syns)
        return ' '.join(words)

    def random_insertion(self, text, n=2):
        words = text.split()
        for _ in range(n):
            idx = random.randint(0, len(words) - 1)
            syns = self._get_synonyms(words[idx])
            if syns:
                words.insert(random.randint(0, len(words)), random.choice(syns))
        return ' '.join(words)

    def random_swap(self, text, n=2):
        words = text.split()
        for _ in range(n):
            if len(words) > 1:
                idx = random.randint(0, len(words) - 2)
                words[idx], words[idx + 1] = words[idx + 1], words[idx]
        return ' '.join(words)

    def random_deletion(self, text, p=0.2):
        words = text.split()
        if len(words) <= 1:
            return text
        kept = [w for w in words if random.random() > p]
        return ' '.join(kept) if kept else random.choice(words)

    def augment(self, text, strategy='all'):
        strategies = {
            'sr': self.synonym_replacement,
            'ri': self.random_insertion,
            'rs': self.random_swap,
            'rd': self.random_deletion
        }
        if strategy == 'all':
            result = text
            for name, func in strategies.items():
                if random.random() < getattr(self, f'{name}_prob'):
                    result = func(result)
            return result
        return strategies[strategy](text)

augmenter = TextAugmenter()
sentence = "Machine learning models require large amounts of training data"
print(f"Original: {sentence}")
print(f"SR:       {augmenter.synonym_replacement(sentence, n=2)}")
print(f"RI:       {augmenter.random_insertion(sentence, n=2)}")
print(f"RS:       {augmenter.random_swap(sentence, n=2)}")
print(f"RD:       {augmenter.random_deletion(sentence, p=0.2)}")
print(f"All:      {augmenter.augment(sentence)}")
